{
  "title": "TB Transmission Dynamics Explorer",
  "perWatchSecond": 0.25,
  "levels": [
    {
      "kind": "hook",
      "title": "Contact Rate Impact",
      "goal": "Explore how changing the contact rate (β) affects the number of infectious individuals.",
      "control": {
        "parameter": "beta",
        "label": "Contact Rate",
        "lowEnd": "0.02",
        "highEnd": "0.08"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the contact rate is doubled?",
        "parameter": "beta",
        "value": 0.10
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 10,
        "time": 10,
        "relation": "higher",
        "by": 30
      },
      "effect": "At t = 10 years, the infectious compartment is at least 30 individuals higher when the contact rate is doubled.",
      "prediction": {
        "prompt": "Predict the effect of doubling β on infectious count at year 10.",
        "claimed": "Higher",
        "other": "Lower"
      },
      "passage": {
        "title": "Key Sensitivity Factors",
        "quote": "\"contact rate ($beta$), recruitment rate ($varLambda$), the loss of protection for the vaccination rate ($theta$), and rate of progression from the exposed class to the infectious class ($gamma$) were the most important factors.\""
      },
      "carryForward": "Use the same β value in the next level."
    },
    {
      "kind": "background",
      "title": "Recruitment Rate Influence",
      "goal": "Investigate the effect of varying the recruitment rate (Λ) on the susceptible population.",
      "control": {
        "parameter": "lambda",
        "label": "Recruitment Rate",
        "lowEnd": "10",
        "highEnd": "20"
      },
      "watch": "s",
      "whatIf": {
        "prompt": "What if the recruitment rate is increased by 50%?",
        "parameter": "lambda",
        "value": 22.5
      },
      "difference": {
        "compartment": "s",
        "summary": "at",
        "at": 5,
        "time": 5,
        "relation": "higher",
        "by": 40
      },
      "effect": "At t = 5 years, the susceptible compartment is at least 40 individuals higher with a 50% higher recruitment rate.",
      "prediction": {
        "prompt": "Predict the effect of a 50% higher Λ on susceptible count at year 5.",
        "claimed": "Higher",
        "other": "Lower"
      },
      "passage": null,
      "carryForward": "Keep the modified Λ for subsequent levels."
    },
    {
      "kind": "idea",
      "title": "Progression Rate Sensitivity",
      "goal": "Examine how the progression rate from exposed to infectious (γ) alters the peak of infectious cases.",
      "control": {
        "parameter": "gamma",
        "label": "Progression Rate",
        "lowEnd": "0.3",
        "highEnd": "0.6"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if γ is halved?",
        "parameter": "gamma",
        "value": 0.24
      },
      "difference": {
        "compartment": "i",
        "summary": "lowest",
        "at": null,
        "time": 15,
        "relation": "lower",
        "by": 50
      },
      "effect": "By year 15, the lowest infectious count is at least 50 individuals lower when γ is halved.",
      "prediction": {
        "prompt": "Predict the effect of halving γ on the minimum infectious count by year 15.",
        "claimed": "Lower",
        "other": "Higher"
      },
      "passage": null,
      "carryForward": "Use the reduced γ value in the next scenario."
    },
    {
      "kind": "method",
      "title": "Vaccine Waning Effect",
      "goal": "Assess the impact of increasing the loss of vaccine protection (θ) on the vaccinated compartment.",
      "control": {
        "parameter": "theta",
        "label": "Vaccine Waning Rate",
        "lowEnd": "0.3",
        "highEnd": "0.7"
      },
      "watch": "v",
      "whatIf": {
        "prompt": "What if θ is doubled?",
        "parameter": "theta",
        "value": 1.0
      },
      "difference": {
        "compartment": "v",
        "summary": "at",
        "at": 8,
        "time": 8,
        "relation": "lower",
        "by": 20
      },
      "effect": "At t = 8 years, the vaccinated compartment is at least 20 individuals lower when θ is doubled.",
      "prediction": {
        "prompt": "Predict the effect of doubling θ on vaccinated count at year 8.",
        "claimed": "Lower",
        "other": "Higher"
      },
      "passage": null,
      "carryForward": "Maintain the increased θ for the final analysis."
    },
    {
      "kind": "evaluation",
      "title": "Combined Parameter Shift",
      "goal": "Evaluate the cumulative effect of higher β, higher Λ, lower γ, and higher θ on total infectious burden over 20 years.",
      "control": {
        "parameter": "beta",
        "label": "Contact Rate (adjusted)",
        "lowEnd": "0.04",
        "highEnd": "0.09"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if all four parameters are set to their modified values simultaneously?",
        "parameter": "gamma",
        "value": 0.24
      },
      "difference": {
        "compartment": "i",
        "summary": "total",
        "at": null,
        "time": 20,
        "relation": "higher",
        "by": 1200
      },
      "effect": "Over 20 years, the total number of infectious individuals is at least 1200 higher with the combined parameter changes.",
      "prediction": {
        "prompt": "Predict the total infectious count over 20 years with all modified parameters.",
        "claimed": "Higher",
        "other": "Lower"
      },
      "passage": null,
      "carryForward": "This concludes the exploration."
    }
  ],
  "limits": [
    "All time values are in years.",
    "Controls adjust rates only (no starting values).",
    "Differences are measured at specified times or totals.",
    "Predictions require choosing higher or lower."
  ]
}
